import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';

export type AgentDocsComponent = {
  slug: string;
  name: string;
  description: string;
  importPath: string;
  packageEntryPoint?: string;
  markdown: string;
};

export const agentDocsPaths = {
  index: '/llms.txt',
  full: '/llms-full.txt',
  component: (slug: string) => `/io/${slug}.md`,
  overviewPage: '/?path=/docs/io-overview--docs',
  forAgentsSection: '/?path=/docs/io-overview--docs#for-agents',
};

export const generatedBannerPrefix =
  '<!-- Generated by `pnpm stories:generate-docs`';

const title = '# io Design System';

const summary =
  "> Temporal's design system for product UI: Svelte 5 components, semantic theme tokens, and an icon library. Components ship in `@temporalio/ui`; import each one from its own entry point, `$lib/io/<name>` inside temporalio/ui or `@temporalio/ui/io/<name>` in other apps.";

const notes =
  "Every component has a Markdown page with its description, usage guidance, Do / Don't rules, and API reference, generated from the same source as its Storybook docs page. Prefer semantic theme classes such as `text-primary`, `bg-surface-primary`, and `border-primary` so UI follows the light and dark themes.";

export const stripGeneratedBanner = (markdown: string) =>
  markdown.replace(/^<!--[\s\S]*?-->\s*/, '');

function generatedMarkdownFiles(directory: string): string[] {
  return readdirSync(directory, { withFileTypes: true }).flatMap((entry) => {
    const path = join(directory, entry.name);
    if (entry.isDirectory()) return generatedMarkdownFiles(path);
    return entry.name.endsWith('.md') &&
      !entry.name.endsWith('.usage.md') &&
      readFileSync(path, 'utf8').startsWith(generatedBannerPrefix)
      ? [path]
      : [];
  });
}

function packageEntryPoints(root: string): Set<string> {
  const { exports = {} } = JSON.parse(
    readFileSync(join(root, 'package.json'), 'utf8'),
  ) as { exports?: Record<string, unknown> };
  return new Set(Object.keys(exports));
}

export function loadComponents(root: string): AgentDocsComponent[] {
  const ioDirectory = join(root, 'src', 'lib', 'io');
  const entryPoints = packageEntryPoints(root);

  return generatedMarkdownFiles(ioDirectory)
    .map((path) => {
      const markdown = stripGeneratedBanner(readFileSync(path, 'utf8'));
      const folder = relative(ioDirectory, dirname(path)).split('\\').join('/');
      const slug = folder.split('/').at(-1) ?? folder;
      const [, name = slug, paragraph = ''] =
        markdown.match(/^# (.+)\n+([^#][\s\S]*?)\n\n/) ?? [];
      return {
        slug,
        name,
        description: paragraph.replace(/\s+/g, ' ').trim(),
        importPath: `$lib/io/${folder}`,
        packageEntryPoint: entryPoints.has(`./io/${folder}`)
          ? `@temporalio/ui/io/${folder}`
          : undefined,
        markdown,
      };
    })
    .sort((a, b) => a.name.localeCompare(b.name));
}

export function buildLlmsIndex(
  origin: string,
  components: AgentDocsComponent[],
): string {
  const url = (path: string) => `${origin}${path}`;
  const componentLines = components.map(
    (component) =>
      `- [${component.name}](${url(agentDocsPaths.component(component.slug))}): ${component.description}`,
  );

  return [
    title,
    summary,
    notes,
    '## Docs',
    [
      `- [Overview](${url(agentDocsPaths.overviewPage)}): Getting started, the guides, and every component.`,
      `- [Full documentation](${url(agentDocsPaths.full)}): Every component's Markdown page in one file.`,
      `- [For agents](${url(agentDocsPaths.forAgentsSection)}): The files on this site written for AI tools, and how to point an assistant at them.`,
    ].join('\n'),
    '## Components',
    componentLines.join('\n'),
  ]
    .join('\n\n')
    .concat('\n');
}

export function buildLlmsFull(components: AgentDocsComponent[]): string {
  return [
    [title, summary, notes].join('\n\n'),
    ...components.map((component) => component.markdown.trim()),
  ]
    .join('\n\n---\n\n')
    .concat('\n');
}
